import { isArchived } from "@/lib/soft-delete";
import type { CommentId } from "@/types/common";
import type { CommentWithAuthor } from "@/types/comment";
import type { Actor } from "@/types/member";
import type { ReactElement } from "react";
import { commentResource } from "../permission/resources";

export type CommentItemProps = {
  comment: CommentWithAuthor;
  actor: Actor;
  depth: number;
  onEdit?: (commentId: CommentId) => void;
  onDelete?: (commentId: CommentId) => void;
};

/** Replies are indented once; deeper nesting is flattened by the thread. */
const INDENT_REM = 2;

export function CommentItem(props: CommentItemProps): ReactElement | null {
  const { comment, actor, depth, onEdit, onDelete } = props;
  const resource = commentResource(comment);

  // Authors may edit and delete their own comments below the matrix rank —
  // that escalation lives in `can()`, not here.
  const mayEdit = can(actor, "comment:update", resource);
  const mayDelete = can(actor, "comment:delete", resource);

  if (isArchived(comment)) {
    return (
      <li className="text-sm italic text-neutral-500">
        This comment was deleted.
      </li>
    );
  }

  return (
    <li
      className={cn("comment-item flex gap-2 py-2")}
      style={{ marginLeft: `${Math.min(depth, 1) * INDENT_REM}rem` }}
    >
      <Avatar
        name={comment.author.name}
        src={comment.author.avatarUrl}
        size="sm"
      />

      <div className="min-w-0 flex-1">
        <p className="text-sm">
          <strong>{comment.author.name}</strong>
          <span className="ml-2 text-neutral-500">
            {formatRelative(comment.createdAt)}
          </span>
          {comment.editedAt !== null ? (
            <span className="ml-2 text-xs text-neutral-400">(edited)</span>
          ) : null}
        </p>

        <div
          className="mt-1 text-sm"
          dangerouslySetInnerHTML={{ __html: highlightMentions(comment.body) }}
        />

        {mayEdit || mayDelete ? (
          <div className="mt-1 flex gap-1">
            {mayEdit && onEdit !== undefined ? (
              <Button
                variant="ghost"
                size="sm"
                onClick={() => onEdit(comment.id)}
              >
                Edit
              </Button>
            ) : null}
            {mayDelete && onDelete !== undefined ? (
              <Button
                variant="ghost"
                size="sm"
                onClick={() => onDelete(comment.id)}
              >
                Delete
              </Button>
            ) : null}
          </div>
        ) : null}
      </div>
    </li>
  );
}
/**
 * Very small Markdown subset renderer for issue descriptions and comments.
 *
 * Supported: ATX headings, fenced and inline code, bold, italic, links,
 * unordered lists and paragraphs. Everything else is escaped — this renderer
 * is applied to user input, so escaping first and un-escaping only the
 * constructs below is the whole safety argument.
 */

function escapeHtml(text: string): string {
  return text
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

function renderInline(text: string): string {
  return escapeHtml(text)
    .replace(/`([^`]+)`/g, "<code>$1</code>")
    .replace(/\*\*([^*]+)\*\*/g, "<strong>$1</strong>")
    .replace(/(^|[^*])\*([^*]+)\*/g, "$1<em>$2</em>")
    .replace(
      /\[([^\]]+)\]\((https?:\/\/[^\s)]+|\/[^\s)]*)\)/g,
      '<a href="$2">$1</a>',
    );
}

/** Renders the supported subset to HTML. Unsupported syntax stays literal. */
export function renderMarkdown(source: string): string {
  const blocks: string[] = [];
  const lines = source.replace(/\r\n/g, "\n").split("\n");

  let listBuffer: string[] = [];
  let codeBuffer: string[] | null = null;

  const flushList = (): void => {
    if (listBuffer.length === 0) return;
    blocks.push(`<ul>${listBuffer.map((li) => `<li>${li}</li>`).join("")}</ul>`);
    listBuffer = [];
  };

  for (const line of lines) {
    if (line.trimStart().startsWith("```")) {
      if (codeBuffer === null) {
        flushList();
        codeBuffer = [];
      } else {
        blocks.push(`<pre><code>${escapeHtml(codeBuffer.join("\n"))}</code></pre>`);
        codeBuffer = null;
      }
      continue;
    }

    if (codeBuffer !== null) {
      codeBuffer.push(line);
      continue;
    }

    const heading = /^(#{1,3})\s+(.*)$/.exec(line);
    if (heading) {
      flushList();
      const level = heading[1]?.length ?? 1;
      blocks.push(`<h${level}>${renderInline(heading[2] ?? "")}</h${level}>`);
      continue;
    }

    const listItem = /^\s*[-*]\s+(.*)$/.exec(line);
    if (listItem) {
      listBuffer.push(renderInline(listItem[1] ?? ""));
      continue;
    }

    if (line.trim() === "") {
      flushList();
      continue;
    }

    flushList();
    blocks.push(`<p>${renderInline(line.trim())}</p>`);
  }

  if (codeBuffer !== null) {
    blocks.push(`<pre><code>${escapeHtml(codeBuffer.join("\n"))}</code></pre>`);
  }
  flushList();

  return blocks.join("\n");
}

/** Plain-text projection, for search indexing, digests and email previews. */
export function stripMarkdown(source: string): string {
  return source
    .replace(/```[\s\S]*?```/g, " ")
    .replace(/`([^`]+)`/g, "$1")
    .replace(/!\[[^\]]*\]\([^)]*\)/g, " ")
    .replace(/\[([^\]]+)\]\([^)]*\)/g, "$1")
    .replace(/^#{1,6}\s+/gm, "")
    .replace(/^\s*[-*]\s+/gm, "")
    .replace(/\*\*([^*]+)\*\*/g, "$1")
    .replace(/\*([^*]+)\*/g, "$1")
    .replace(/\s+/g, " ")
    .trim();
}

/** A single-line snippet, truncated on a word boundary with an ellipsis. */
export function excerpt(source: string, maxLength = 160): string {
  const text = stripMarkdown(source);
  if (text.length <= maxLength) return text;

  const cut = text.slice(0, maxLength);
  const lastSpace = cut.lastIndexOf(" ");
  return `${(lastSpace > maxLength * 0.6 ? cut.slice(0, lastSpace) : cut).trimEnd()}…`;
}
/**
 * Wires every subscriber at process start. Called once from `src/instrumentation.ts`; the only module that knows the full listener set.
 *
 * Must call (do not reimplement): subscribe, registerActivityListeners, registerSearchListeners, registerUsageListeners, registerWebhookListeners
 */
import { subscribe } from "@/lib/event-bus";
import { createLogger } from "@/lib/logger";
import { enqueue } from "@/server/jobs/queue";
import { toIsoTimestamp } from "@/types/common";
import { registerActivityListeners } from "./activity-service";
import { registerSearchListeners } from "./search-service";
import { registerUsageListeners } from "./usage-service";
import { registerWebhookListeners } from "./webhook-service";
import type { Unsubscribe } from "@/types/event";

/**
 * Importing this module also loads `notification-service` transitively, which
 * attaches the notification fan-out on first import — that hub has no
 * `register*` entry point of its own.
 */
import "./notification-service";

const logger = createLogger("event-registry");

/** Non-null between `registerEventHandlers()` and `unregisterEventHandlers()`. */
let detach: Unsubscribe | null = null;

/**
 * Attaches every subscriber exactly once. Idempotent: `instrumentation.ts`
 * runs per server process, but a hot reload in dev can call it again and must
 * not double-deliver every event.
 */
export function registerEventHandlers(): void {
  if (detach !== null) return;

  const offs: Unsubscribe[] = [
    registerActivityListeners(),
    registerSearchListeners(),
    registerUsageListeners(),
    registerWebhookListeners(),
    registerDigestBridge(),
  ];

  detach = () => {
    for (const off of offs) off();
  };

  logger.info("event handlers registered", { groups: offs.length });
}

export function unregisterEventHandlers(): void {
  detach?.();
  detach = null;
}

/**
 * The one piece of wiring that belongs to no single service: turning a
 * `digest.due` event into a queued job. Keeping it here rather than inside
 * `DigestService` stops the service layer from depending on the job layer.
 */
function registerDigestBridge(): Unsubscribe {
  return subscribe("digest.due", (payload) => {
    enqueue({
      id: `digest:${payload.orgId}:${payload.recipientId}`,
      kind: "digest-email",
      runAt: toIsoTimestamp(new Date()),
      attempts: 0,
      payload: {
        orgId: payload.orgId,
        recipientId: payload.recipientId,
        windowStart: payload.windowStart,
      },
    });
  });
}
import type {
  IsoTimestamp,
  MemberId,
  OrgId,
  SoftDeletable,
  TenantScoped,
  Timestamps,
  UserId,
  InvitationId,
} from "./common";

/**
 * Taskflow RBAC roles, ordered from most to least privileged. `ROLE_RANK`
 * below is the single source of truth for "at least this role" comparisons —
 * never compare role strings directly.
 */
export type Role = "owner" | "admin" | "member" | "viewer";

export const ROLES: readonly Role[] = ["owner", "admin", "member", "viewer"];

export const ROLE_RANK: Readonly<Record<Role, number>> = {
  owner: 4,
  admin: 3,
  member: 2,
  viewer: 1,
};

export type MemberStatus = "active" | "invited" | "suspended";

export interface User extends Timestamps {
  readonly id: UserId;
  readonly email: string;
  readonly name: string;
  readonly avatarUrl: string | null;
  readonly timezone: string;
  readonly emailVerifiedAt: IsoTimestamp | null;
}

export interface Member extends Timestamps, TenantScoped, SoftDeletable {
  readonly id: MemberId;
  readonly userId: UserId;
  readonly role: Role;
  readonly status: MemberStatus;
  readonly invitedBy: UserId | null;
  readonly joinedAt: IsoTimestamp | null;
  readonly lastSeenAt: IsoTimestamp | null;
}

/** A member joined with the user record it points at, for list UIs. */
export interface MemberWithUser extends Member {
  readonly user: User;
}

export interface Invitation extends Timestamps, TenantScoped {
  readonly id: InvitationId;
  readonly email: string;
  readonly role: Role;
  readonly invitedBy: UserId;
  readonly token: string;
  readonly expiresAt: IsoTimestamp;
  readonly acceptedAt: IsoTimestamp | null;
  readonly revokedAt: IsoTimestamp | null;
}

/**
 * The authenticated principal for one request, always resolved for exactly one
 * organization. Everything that authorizes a mutation takes an `Actor` — see
 * `can()` in `src/lib/permissions.ts` and `assertOrgScope()` in
 * `src/lib/tenant.ts`.
 */
export interface Actor {
  readonly userId: UserId;
  readonly orgId: OrgId;
  readonly role: Role;
  /** Staff impersonation / internal tooling escape hatch. Defaults to false. */
  readonly isPlatformStaff?: boolean;
}

export interface SessionPrincipal {
  readonly userId: UserId;
  readonly email: string;
  readonly activeOrgId: OrgId | null;
  readonly expiresAt: IsoTimestamp;
}

/** True when `role` is at least as privileged as `atLeast`. */
export function hasRoleAtLeast(role: Role, atLeast: Role): boolean {
  return ROLE_RANK[role] >= ROLE_RANK[atLeast];
}

